<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientAllowController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientListController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientCreateController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientRetrieveController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientUpdateController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientDeleteController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientEnableController;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest\TrustedClientDisableController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Create\CreateTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Create\TrustedClientCreateAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Update\TrustedClientUpdateAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Update\UpdateTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Retrieve\RetrieveTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Retrieve\TrustedClientRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\List\ListTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\List\TrustedClientListAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Delete\DeleteTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Delete\TrustedClientDeleteAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Enable\EnableTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Enable\TrustedClientEnableAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Disable\DisableTrustedClientOnlyForRootAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Disable\TrustedClientDisableAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driven\TrustedClientReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driven\TrustedClientWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientWriteGateway;

class TrustedClientPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[TrustedClientReadGateway::class] = \DI\autowire(TrustedClientReadRepositoryAdapter::class);
        $def[TrustedClientWriteGateway::class] = \DI\autowire(TrustedClientWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/trusted-clients', [$this, 'setRoutesForTrustedClient']);
        $collector->group('/api/me/acl/access/trusted-clients', [$this, 'setRoutesForTrustedClientAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(TrustedClientCreateAllowDecision::class, CreateTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(TrustedClientUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(TrustedClientUpdateAllowDecision::class, UpdateTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(TrustedClientRetrieveAllowDecision::class, RetrieveTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(TrustedClientListAllowDecision::class, ListTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientDeleteAllowDecision::class, DeleteTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
        $listener->registerListener(TrustedClientEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
        $listener->registerListener(TrustedClientEnableAllowDecision::class, EnableTrustedClientOnlyForRootAllow::class);
        $listener->registerListener(TrustedClientDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
        $listener->registerListener(TrustedClientDisableAllowDecision::class, DisableTrustedClientOnlyForRootAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("trusted-client", "list", "READ");
            $handler->registerResourceAction("trusted-client", "create", "WRITE");
            $handler->registerResourceAction("trusted-client", "retrieve", "READ");
            $handler->registerResourceAction("trusted-client", "update", "WRITE");
            $handler->registerResourceAction("trusted-client", "delete", "WRITE");
            $handler->registerResourceAction("trusted-client", "enable", "WRITE");
            $handler->registerResourceAction("trusted-client", "disable", "WRITE");

            $handler->registerResourceAttribute("trusted-client", "code", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "allowAllScopes", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "publicAllow", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "allowedRedirects", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "secretOauth", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "backChannelLogoutUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "backChannelLogoutSessionRequired", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "frontChannelLogoutUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "frontChannelLogoutSessionRequired", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "enabled", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "registrationAccess", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "clientName", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "logoUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "clientUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "policyUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "tosUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "tokenEndpointAuthMethod", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "grantTypesJson", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "responseTypesJson", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "dynamicallyRegistered", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "registeredAt", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "allowedScopesM2m", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "m2mTokenTtlSeconds", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "requestObjectSigningAlg", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "jwksUri", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "jwksJson", "MANAGE");
            $handler->registerResourceAttribute("trusted-client", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForTrustedClientAcl(RouteCollectorProxy $trustedClientGroup): void
    {
        $trustedClientGroup->get('', [TrustedClientAllowController::class, 'genericAllow']);
        $trustedClientGroup->get('/{uid}', [TrustedClientAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTrustedClient(RouteCollectorProxy $trustedClientGroup): void
    {
        $trustedClientGroup->get('', [TrustedClientListController::class, 'list']);
        $trustedClientGroup->post('', [TrustedClientCreateController::class, 'create']);
        $trustedClientGroup->get('/{uid}', [TrustedClientRetrieveController::class, 'retrieve']);
        $trustedClientGroup->put('/{uid}', [TrustedClientUpdateController::class, 'update']);
        $trustedClientGroup->delete('/{uid}', [TrustedClientDeleteController::class, 'delete']);
        $trustedClientGroup->delete('', [TrustedClientDeleteController::class, 'deleteAllForQuery']);
        $trustedClientGroup->get('/~/delete-status/{uid}', [TrustedClientDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $trustedClientGroup->patch('/~/enable', [TrustedClientEnableController::class, 'enableAllForQuery']);
        $trustedClientGroup->patch('/{uid}/enable', [TrustedClientEnableController::class, 'enable']);
        $trustedClientGroup->get('/~/enable-status/{uid}', [TrustedClientEnableController::class, 'checkEnableAllForQueryStatus']);
        $trustedClientGroup->patch('/~/disable', [TrustedClientDisableController::class, 'disableAllForQuery']);
        $trustedClientGroup->patch('/{uid}/disable', [TrustedClientDisableController::class, 'disable']);
        $trustedClientGroup->get('/~/disable-status/{uid}', [TrustedClientDisableController::class, 'checkDisableAllForQueryStatus']);
    }
}
